async function run() {
  const items = (typeof event !== 'undefined' && event && event.items) || [];
  for (const item of items) {
    const j = await judge.urgent(item);
    if (j.p >= 0.5) {
      const from = item.from_name || item.from || '';
      const subject = item.subject || '(sem assunto)';
      const detail = item.snippet || '';
      const text = `🚨 Urgente: "${subject}" (${from})${detail ? ' — ' + detail : ''}`;
      await notify.send({ text });
    }
  }
}
